package com.metalurgica.sistemagestaoindustrial.resource;
import com.metalurgica.sistemagestaoindustrial.domain.StatusImportacao; import com.metalurgica.sistemagestaoindustrial.dto.response.*; import com.metalurgica.sistemagestaoindustrial.service.ImportacaoProducaoService; import com.metalurgica.sistemagestaoindustrial.service.QualidadeDadosService; import org.springframework.data.domain.*; import org.springframework.data.web.PageableDefault; import org.springframework.format.annotation.DateTimeFormat; import org.springframework.web.bind.annotation.*; import java.time.OffsetDateTime;
@RestController @RequestMapping("/api/v1/empresas/{empresaId}/importacoes/producao") public class ImportacaoHistoricoResource {
 private final ImportacaoProducaoService service; private final QualidadeDadosService qualidadeDadosService; public ImportacaoHistoricoResource(ImportacaoProducaoService service, QualidadeDadosService qualidadeDadosService){this.service=service;this.qualidadeDadosService=qualidadeDadosService;}
 @GetMapping public Page<ImportacaoProducaoResponse> list(@PathVariable Long empresaId,@RequestParam(required=false) Long setorId,@RequestParam(required=false) StatusImportacao status,@RequestParam(required=false) String nomeArquivo,@RequestParam(required=false) @DateTimeFormat(iso=DateTimeFormat.ISO.DATE_TIME) OffsetDateTime dataInicio,@RequestParam(required=false) @DateTimeFormat(iso=DateTimeFormat.ISO.DATE_TIME) OffsetDateTime dataFim,@PageableDefault(size=20) Pageable p){return service.list(empresaId,setorId,status,nomeArquivo,dataInicio,dataFim,p);}
 @GetMapping("/{importacaoId}") public ImportacaoProducaoResponse get(@PathVariable Long empresaId,@PathVariable Long importacaoId){return service.get(empresaId,importacaoId);}
 @GetMapping("/{importacaoId}/linhas") public Page<ResultadoLinhaImportacaoResponse> lines(@PathVariable Long empresaId,@PathVariable Long importacaoId,@PageableDefault(size=50) Pageable p){return service.lines(empresaId,importacaoId,p);}
 @GetMapping("/{importacaoId}/qualidade") public QualidadeImportacaoResponse quality(@PathVariable Long empresaId,@PathVariable Long importacaoId){return qualidadeDadosService.quality(empresaId, importacaoId);}
}
